# # # # # # # # # # # # # # # # def predict():

# # # # # # # # # # # # # # # #     try:
# # # # # # # # # # # # # # # #         data = request.get_json()

# # # # # # # # # # # # # # # #         category = data["category"]
# # # # # # # # # # # # # # # #         product = data["product"]
# # # # # # # # # # # # # # # #         month = data["month"]
# # # # # # # # # # # # # # # #         price = float(data["price"])

# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         # HISTORY FILTER
# # # # # # # # # # # # # # # #         # =====================================================
