# # # # # # # # # # # # # # # #         if history.empty:
# # # # # # # # # # # # # # # #             return jsonify({"error": "No product history found"})

# # # # # # # # # # # # # # # #         history = history.sort_values("MonthEncoded").reset_index(drop=True)

# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         # LATEST FEATURES
# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         latest_units = history.iloc[-1]["Units Sold"]
# # # # # # # # # # # # # # # #         rolling_avg = history["Units Sold"].tail(3).mean()

# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         # ENCODING
# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         category_encoded = category_encoder.transform([category])[0]
# # # # # # # # # # # # # # # #         product_encoded = product_encoder.transform([product])[0]

# # # # # # # # # # # # # # # #         month_encoded = month_map.get(month.strip(), None)
# # # # # # # # # # # # # # # #         if month_encoded is None:
# # # # # # # # # # # # # # # #             return jsonify({"error": "Invalid month selected"})

# # # # # # # # # # # # # # # #         # seasonal encoding
# # # # # # # # # # # # # # # #         month_sin = np.sin(2 * np.pi * month_encoded / 12)
# # # # # # # # # # # # # # # #         month_cos = np.cos(2 * np.pi * month_encoded / 12)

# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         # FEATURE VECTOR
# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         features = np.array([[
# # # # # # # # # # # # # # # #             category_encoded,
# # # # # # # # # # # # # # # #             product_encoded,
# # # # # # # # # # # # # # # #             month_encoded,
# # # # # # # # # # # # # # # #             month_sin,
# # # # # # # # # # # # # # # #             month_cos,
# # # # # # # # # # # # # # # #             latest_units,
# # # # # # # # # # # # # # # #             rolling_avg
# # # # # # # # # # # # # # # #         ]])

# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         # PREDICT
# # # # # # # # # # # # # # # #         # =====================================================
