# # # # # # # # # # # # # # # #         # safety clamp
# # # # # # # # # # # # # # # #         max_allowed = history["Units Sold"].max() * 1.5
# # # # # # # # # # # # # # # #         predicted_units = max(0, min(predicted_units, max_allowed))

# # # # # # # # # # # # # # # #         predicted_sales = predicted_units * price

# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         # RESPONSE
# # # # # # # # # # # # # # # #         # =====================================================
# # # # # # # # # # # # # # # #         return jsonify({

